'use client';

import { useEffect, useMemo, useRef, useState } from 'react';
import { apiJson } from '../../lib/api';

type Team = 'HOME' | 'AWAY';
type ShotResult = 'MADE' | 'MISSED';
type ShotEntryMode = 'COURT' | 'FREE_THROW';
type ReboundType = 'AR' | 'DR';
type LineupPlayer = { number: string; position?: string; name: string; label?: string };
export type ZoneId =
  | 'RESTRICTED_AREA'
  | 'PAINT'
  | 'LEFT_PAINT'
  | 'RIGHT_PAINT'
  | 'LEFT_MID'
  | 'CENTER_MID'
  | 'RIGHT_MID'
  | 'LEFT_CORNER_3'
  | 'LEFT_SHORT_3'
  | 'LEFT_WING_3'
  | 'TOP_3'
  | 'RIGHT_WING_3'
  | 'RIGHT_SHORT_3'
  | 'RIGHT_CORNER_3'
  | 'FREE_THROW_ZONE';

type Match = {
  id: string;
  name: string;
  sport?: 'FOOTBALL' | 'BASKETBALL';
  metadata?: {
    home_team?: string;
    away_team?: string;
    period_count?: number;
    period_minutes?: number;
    lineups?: {
      teams?: Partial<Record<Team, LineupPlayer[]>>;
    };
  } | null;
};

type BasketballStoredState = {
  events?: GameEvent[];
  lineups?: Partial<Record<Team, LineupPlayer[]>> | null;
  timer?: {
    period?: number;
    clock?: string;
  } | null;
};

type GameEvent = {
  id: string;
  type: 'SHOT' | 'REBOUND';
  team: Team;
  playerNumber?: string;
  period: number;
  clock: string;
  timestamp: number;
  x?: number;
  y?: number;
  zoneId?: ZoneId;
  shotResult?: ShotResult;
  points?: 1 | 2 | 3;
  reboundType?: ReboundType;
  reboundAllowedTeam?: Team;
  homeScoreAfter: number;
  awayScoreAfter: number;
  marginAfter: number;
};

export type ZoneShape = {
  id: ZoneId;
  label: string;
  points: 2 | 3;
  d: string;
  textX: number;
  textY: number;
};

const COURT_IMAGE_WIDTH = 722;
const COURT_IMAGE_HEIGHT = 678;
const HOME_PLAYERS = ['0', '1', '3', '4', '7', '9', '10', '11', '30'];
const AWAY_PLAYERS = ['1', '2', '3', '4', '7', '9', '10', '11', '30'];
const TEAM_SHORT: Record<Team, 'H' | 'A'> = { HOME: 'H', AWAY: 'A' };

function fallbackLineup(side: Team): LineupPlayer[] {
  const numbers = side === 'HOME' ? HOME_PLAYERS : AWAY_PLAYERS;
  return numbers.map((number) => ({ number, position: '-', name: `${TEAM_SHORT[side]}${number}` }));
}

function lineupsFromMatch(match: Match | null): Record<Team, LineupPlayer[]> {
  const teams = match?.metadata?.lineups?.teams || {};
  return {
    HOME: teams.HOME?.length ? teams.HOME : fallbackLineup('HOME'),
    AWAY: teams.AWAY?.length ? teams.AWAY : fallbackLineup('AWAY'),
  };
}

