function opponent(team: Team): Team {
  return team === 'HOME' ? 'AWAY' : 'HOME';
}

function eventTime(period: number, clock: string) {
  return `${period}Q ${clock}`;
}

function parseClockSeconds(value: string) {
  const [minutesRaw, secondsRaw = '0'] = value.split(':');
  const minutes = Number(minutesRaw);
  const seconds = Number(secondsRaw);
  if (!Number.isFinite(minutes) || !Number.isFinite(seconds)) return 0;
  return Math.max(0, minutes * 60 + seconds);
}

function formatClockSeconds(totalSeconds: number) {
  const safeSeconds = Math.max(0, Math.floor(totalSeconds));
  const minutes = Math.floor(safeSeconds / 60);
  const seconds = safeSeconds % 60;
  return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
}

function formatElapsedAxis(totalSeconds: number) {
  const safeSeconds = Math.max(0, Math.floor(totalSeconds));
  const minutes = Math.floor(safeSeconds / 60);
  const seconds = safeSeconds % 60;
  return seconds === 0 ? `${minutes}m` : `${minutes}:${String(seconds).padStart(2, '0')}`;
}

export default function BasketballMatchPage({ params }: { params: { id: string } }) {
  const [match, setMatch] = useState<Match | null>(null);
  const [events, setEvents] = useState<GameEvent[]>([]);
  const [selectedTeam, setSelectedTeam] = useState<Team>('HOME');
  const [selectedPlayer, setSelectedPlayer] = useState('7');
  const [selectedShotResult, setSelectedShotResult] = useState<ShotResult>('MADE');
  const [selectedShotEntryMode, setSelectedShotEntryMode] = useState<ShotEntryMode>('COURT');
  const [selectedReboundTeam, setSelectedReboundTeam] = useState<Team | null>(null);
  const [selectedReboundType, setSelectedReboundType] = useState<ReboundType | null>(null);
  const [basketballLineups, setBasketballLineups] = useState<Record<Team, LineupPlayer[]>>({
    HOME: fallbackLineup('HOME'),
    AWAY: fallbackLineup('AWAY'),
  });
  const [eventsLoaded, setEventsLoaded] = useState(false);
  const [lineupsLoaded, setLineupsLoaded] = useState(false);
  const [isLineupEditorOpen, setIsLineupEditorOpen] = useState(false);
  const [period, setPeriod] = useState(1);
  const [clock, setClock] = useState('10:00');
  const [timerRunning, setTimerRunning] = useState(false);
  const [timerResetArmed, setTimerResetArmed] = useState(false);
  const [selectedShot, setSelectedShot] = useState<{ zoneId: ZoneId; x: number; y: number } | null>(null);
  const [marginTooltip, setMarginTooltip] = useState<{ id: string; x: number; y: number; lines: string[] } | null>(null);
  const [error, setError] = useState('');

  const storageKey = `fineplay.basketball.events.${params.id}`;
  const lineupStorageKey = `fineplay.basketball.lineups.${params.id}`;
  const timerStorageKey = `fineplay.basketball.timer.${params.id}`;
  const homeName = match?.metadata?.home_team || 'HOME';
  const awayName = match?.metadata?.away_team || 'AWAY';
  const periodCount = match?.metadata?.period_count || 4;
  const periodMinutes = match?.metadata?.period_minutes || 10;
  const lineups = basketballLineups;
  const clockRef = useRef(clock);
  const periodRef = useRef(period);
  const periodCountRef = useRef(periodCount);
  const periodMinutesRef = useRef(periodMinutes);

  useEffect(() => {
    Promise.all([
      apiJson<Match>(`/matches/${params.id}`),
      apiJson<BasketballStoredState>(`/matches/${params.id}/basketball-state`).catch(() => null),
    ])
      .then(([data, storedState]) => {
        setMatch(data);
        const nextClock = `${String(data.metadata?.period_minutes || 10).padStart(2, '0')}:00`;
        const rawTimer = window.localStorage.getItem(timerStorageKey);
        let localTimer: { period?: number; clock?: string } | null = null;
        if (rawTimer) {
          try {
            const parsed = JSON.parse(rawTimer);
            if (parsed && typeof parsed === 'object') localTimer = parsed;
          } catch {
            localTimer = null;
          }
        }
        const storedTimer = storedState?.timer;
        const restoredPeriod = Number(storedTimer?.period || localTimer?.period || 1);
        const restoredClock = storedTimer?.clock || localTimer?.clock || nextClock;
        setPeriod(Number.isFinite(restoredPeriod) ? Math.min(Math.max(1, restoredPeriod), data.metadata?.period_count || 4) : 1);
        setClock(restoredClock);
        const fallback = lineupsFromMatch(data);
        const storedLineups = storedState?.lineups;
        const rawLineups = window.localStorage.getItem(lineupStorageKey);
        if (Array.isArray(storedLineups?.HOME) && Array.isArray(storedLineups?.AWAY)) {
          setBasketballLineups({ HOME: storedLineups.HOME, AWAY: storedLineups.AWAY });
        } else if (rawLineups) {
          try {
            const parsed = JSON.parse(rawLineups);
            if (Array.isArray(parsed?.HOME) && Array.isArray(parsed?.AWAY)) {
              setBasketballLineups(parsed);
            } else {
              setBasketballLineups(fallback);
            }
          } catch {
            setBasketballLineups(fallback);
          }
        } else {
          setBasketballLineups(fallback);
        }
        const rawEvents = window.localStorage.getItem(storageKey);
        if (Array.isArray(storedState?.events) && storedState.events.length > 0) {
          setEvents(storedState.events);
        } else if (rawEvents) {
          try {
            const parsed = JSON.parse(rawEvents);
            setEvents(Array.isArray(parsed) ? parsed : []);
          } catch {
            setEvents([]);
          }
        } else {
          setEvents([]);
        }
        setEventsLoaded(true);
        setLineupsLoaded(true);
      })
      .catch((loadError) => {
        setEventsLoaded(true);
        setError(loadError instanceof Error ? loadError.message : 'Failed to load match');
      });
  }, [lineupStorageKey, params.id, storageKey]);

  useEffect(() => {
    if (!eventsLoaded) return;
    window.localStorage.setItem(storageKey, JSON.stringify(events));
    window.localStorage.setItem(timerStorageKey, JSON.stringify({ period, clock }));
    apiJson<{ ok: boolean }>(`/matches/${params.id}/basketball-state`, {
      method: 'PUT',
      body: JSON.stringify({ events, lineups: basketballLineups, timer: { period, clock } }),
    }).catch(() => undefined);
  }, [basketballLineups, clock, events, eventsLoaded, params.id, period, storageKey, timerStorageKey]);

  useEffect(() => {
    if (!lineupsLoaded) return;
    window.localStorage.setItem(lineupStorageKey, JSON.stringify(basketballLineups));
  }, [basketballLineups, lineupStorageKey, lineupsLoaded]);

  useEffect(() => {
    clockRef.current = clock;
  }, [clock]);

  useEffect(() => {
    periodRef.current = period;
  }, [period]);

  useEffect(() => {
    periodCountRef.current = periodCount;
    periodMinutesRef.current = periodMinutes;
  }, [periodCount, periodMinutes]);

  useEffect(() => {
    if (!timerRunning) return undefined;
    const timer = window.setInterval(() => {
      const nextSeconds = parseClockSeconds(clockRef.current) - 1;
      if (nextSeconds <= 0) {
        const currentPeriod = periodRef.current;
        const maxPeriod = periodCountRef.current;
        setTimerRunning(false);
        setTimerResetArmed(false);
        if (currentPeriod < maxPeriod) {
          const nextPeriod = currentPeriod + 1;
          const nextClock = formatClockSeconds(periodMinutesRef.current * 60);
          periodRef.current = nextPeriod;
          clockRef.current = nextClock;
          setPeriod(nextPeriod);
          setClock(nextClock);
        } else {
          clockRef.current = '00:00';
          setClock('00:00');
        }
        return;
      }
      const nextClock = formatClockSeconds(nextSeconds);
      clockRef.current = nextClock;
      setClock(nextClock);
    }, 1000);
    return () => window.clearInterval(timer);
  }, [timerRunning]);

  const score = useMemo(() => events.reduce(
    (acc, event) => ({
      home: event.homeScoreAfter,
      away: event.awayScoreAfter,
    }),
    { home: 0, away: 0 }
  ), [events]);

  const zoneStats = useMemo(() => {
    const stats = new Map<ZoneId, { made: number; attempts: number }>();
    ZONES.forEach((zone) => stats.set(zone.id, { made: 0, attempts: 0 }));
    events.forEach((event) => {
      if (event.type !== 'SHOT' || !event.zoneId) return;
      const current = stats.get(event.zoneId);
      if (!current) return;
      current.attempts += 1;
      if (event.shotResult === 'MADE') current.made += 1;
    });
    return stats;
  }, [events]);

  const reboundStats = useMemo(() => {
    const initial = {
      HOME: { ar: 0, dr: 0, ra: 0 },
      AWAY: { ar: 0, dr: 0, ra: 0 },
    };
    events.forEach((event) => {
      if (event.type !== 'REBOUND' || !event.reboundType) return;
      if (event.reboundType === 'AR') initial[event.team].ar += 1;
      if (event.reboundType === 'DR') initial[event.team].dr += 1;
      if (event.reboundAllowedTeam) initial[event.reboundAllowedTeam].ra += 1;
    });
    return initial;
  }, [events]);

  const marginPoints = useMemo(
    () => events.filter((event) => event.type === 'SHOT' && event.shotResult === 'MADE'),
    [events]
  );
  const canSubmitShot = Boolean(
    selectedTeam &&
    selectedPlayer.trim() &&
    (selectedShotEntryMode === 'FREE_THROW' || (selectedShot?.zoneId && selectedShotResult))
  );
  const canSubmitRebound = Boolean(selectedReboundTeam && selectedReboundType);

  const addShot = () => {
    if (!canSubmitShot) {
      setError('선수, 구역, 슛 결과를 모두 선택하세요.');
      return;
    }
    const zone = selectedShotEntryMode === 'COURT' && selectedShot ? ZONES.find((item) => item.id === selectedShot.zoneId) : null;
    if (selectedShotEntryMode === 'COURT' && !zone) return;
    const points = selectedShotEntryMode === 'FREE_THROW' ? 1 : zone?.points || 2;
    const result: ShotResult = selectedShotEntryMode === 'FREE_THROW' ? 'MADE' : selectedShotResult;
    const nextHome = selectedTeam === 'HOME' && result === 'MADE' ? score.home + points : score.home;
    const nextAway = selectedTeam === 'AWAY' && result === 'MADE' ? score.away + points : score.away;
    const event: GameEvent = {
      id: crypto.randomUUID(),
      type: 'SHOT',
      team: selectedTeam,
      playerNumber: selectedPlayer,
      period,
      clock,
      timestamp: Date.now(),
      x: selectedShotEntryMode === 'COURT' ? selectedShot?.x : undefined,
      y: selectedShotEntryMode === 'COURT' ? selectedShot?.y : undefined,
      zoneId: selectedShotEntryMode === 'FREE_THROW' ? 'FREE_THROW_ZONE' : selectedShot?.zoneId,
      shotResult: result,
      points: points as 1 | 2 | 3,
      homeScoreAfter: nextHome,
      awayScoreAfter: nextAway,
      marginAfter: nextHome - nextAway,
    };
    setEvents((prev) => [...prev, event]);
    setSelectedTeam('HOME');
    setSelectedPlayer('7');
    setSelectedShot(null);
    setSelectedShotResult('MADE');
    setSelectedShotEntryMode('COURT');
    setError('');
  };

  const addRebound = () => {
    if (!canSubmitRebound) {
      setError('팀과 리바운드 타입을 모두 선택하세요.');
      return;
    }
    const reboundTeam = selectedReboundTeam;
    const reboundType = selectedReboundType;
    if (!reboundTeam || !reboundType) return;
    const reboundAllowedTeam = reboundType === 'AR' ? opponent(reboundTeam) : undefined;
    const event: GameEvent = {
      id: crypto.randomUUID(),
      type: 'REBOUND',
      team: reboundTeam,
      playerNumber: selectedPlayer,
      period,
      clock,
      timestamp: Date.now(),
      reboundType,
      reboundAllowedTeam,
      homeScoreAfter: score.home,
      awayScoreAfter: score.away,
      marginAfter: score.home - score.away,
    };
    setEvents((prev) => [...prev, event]);
    setSelectedReboundTeam(null);
    setSelectedReboundType(null);
    setError('');
  };

  const undo = () => {
    setEvents((prev) => prev.slice(0, -1));
    setSelectedShot(null);
  };

  const reset = () => {
    if (!window.confirm('농구 기록을 초기화할까요? 로컬에 저장된 이 경기의 농구 이벤트가 삭제됩니다.')) return;
    setEvents([]);
    setSelectedShot(null);
    setSelectedShotEntryMode('COURT');
  };

  const exportJson = () => {
    const payload = {
      exportedAt: new Date().toISOString(),
      match,
      events,
      stats: {
        reboundStats,
        marginPoints,
      },
    };
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = `basketball-live-stats-${params.id}.json`;
    anchor.click();
    URL.revokeObjectURL(url);
  };

  const updateLineupPlayer = (side: Team, index: number, field: keyof LineupPlayer, value: string) => {
    setBasketballLineups((prev) => ({
      ...prev,
      [side]: prev[side].map((player, playerIndex) => (
        playerIndex === index ? { ...player, [field]: field === 'number' ? value.replace(/\D/g, '').slice(0, 3) : value } : player
      )),
    }));
  };

  const addLineupPlayer = (side: Team) => {
    setBasketballLineups((prev) => ({
      ...prev,
      [side]: [...prev[side], { number: '', position: '', name: '' }],
    }));
  };

  const removeLineupPlayer = (side: Team, index: number) => {
    setBasketballLineups((prev) => {
      const removed = prev[side][index];
      const nextSidePlayers = prev[side].filter((_, playerIndex) => playerIndex !== index);
      if (removed?.number === selectedPlayer && side === selectedTeam) {
        const nextPlayer = nextSidePlayers[0] || prev[opponent(side)][0];
        if (nextPlayer) {
          setSelectedTeam(nextSidePlayers[0] ? side : opponent(side));
          setSelectedPlayer(nextPlayer.number);
        }
      }
      return {
        ...prev,
        [side]: nextSidePlayers.length ? nextSidePlayers : fallbackLineup(side),
      };
    });
  };

  const resetTimer = () => {
    if (!timerResetArmed) {
      setTimerResetArmed(true);
      return;
    }
    setTimerRunning(false);
    setClock(formatClockSeconds(periodMinutes * 60));
    setTimerResetArmed(false);
  };

  const lineupRows = (['HOME', 'AWAY'] as Team[]).flatMap((side) => lineups[side].map((player) => ({ ...player, side })));
  const selectedPlayerRow = lineupRows.find((player) => player.side === selectedTeam && player.number === selectedPlayer);
  const shotLogPreview = selectedShotEntryMode === 'FREE_THROW' && selectedPlayer.trim()
    ? `${TEAM_SHORT[selectedTeam]}${selectedPlayer}_FREE_THROW_ZONE_Made`
    : canSubmitShot && selectedShot
    ? `${TEAM_SHORT[selectedTeam]}${selectedPlayer}_${selectedShot.zoneId}_${selectedShotResult === 'MADE' ? 'Made' : 'Missed'}`
    : 'TeamN_Zone_shot';
  const reboundLogPreview = canSubmitRebound && selectedReboundTeam && selectedReboundType ? `${TEAM_SHORT[selectedReboundTeam]}_${selectedReboundType}` : 'Team_Rebound';
  const marginMin = Math.min(-10, ...marginPoints.map((item) => item.marginAfter));
  const marginMax = Math.max(10, ...marginPoints.map((item) => item.marginAfter));
  const periodDurationSeconds = periodMinutes * 60;
  const totalGameSeconds = Math.max(1, periodCount * periodDurationSeconds);
  const currentElapsedSeconds = Math.max(
    0,
    Math.min(
      totalGameSeconds,
      (period - 1) * periodDurationSeconds + Math.max(0, periodDurationSeconds - parseClockSeconds(clock))
    )
  );
  const marginElapsedSeconds = (point: GameEvent) => {
    const elapsedInPeriod = Math.max(0, periodDurationSeconds - parseClockSeconds(point.clock));
    return Math.max(0, Math.min(totalGameSeconds, (point.period - 1) * periodDurationSeconds + elapsedInPeriod));
  };
  const marginVisibleSeconds = Math.max(1, currentElapsedSeconds, ...marginPoints.map(marginElapsedSeconds));
  const marginX = (elapsedSeconds: number) => (elapsedSeconds / marginVisibleSeconds) * 640;
  const marginY = (margin: number) => 200 - ((margin - marginMin) / (marginMax - marginMin || 1)) * 180;
  const marginPointPosition = (point: GameEvent) => {
    const x = marginX(marginElapsedSeconds(point));
    const y = marginY(point.marginAfter);
    return { x, y };
  };
  const marginAxisTicks = Array.from({ length: 5 }, (_, index) => {
    const elapsed = (marginVisibleSeconds / 4) * index;
    return {
      elapsed,
      x: marginX(elapsed),
      label: formatElapsedAxis(elapsed),
    };
  });
  const marginGridXTicks = Array.from({ length: 17 }, (_, index) => (640 / 16) * index);
  const marginGridYTicks = Array.from({ length: 5 }, (_, index) => {
    const value = marginMin + ((marginMax - marginMin) / 4) * index;
    return {
      value,
      y: marginY(value),
    };
  });
  const quarterMarkers = Array.from({ length: Math.max(0, periodCount - 1) }, (_, index) => {
    const markerElapsed = (index + 1) * periodDurationSeconds;
    if (markerElapsed > marginVisibleSeconds) return null;
    return {
      label: `${index + 2}Q`,
      x: marginX(markerElapsed),
    };
  }).filter((marker): marker is { label: string; x: number } => Boolean(marker));
  const orderedMarginPoints = marginPoints
    .slice()
    .sort((left, right) => marginElapsedSeconds(left) - marginElapsedSeconds(right) || left.timestamp - right.timestamp);
  const marginZeroY = marginY(0);
  const marginStepLine = (() => {
    if (orderedMarginPoints.length === 0) return `0,${marginZeroY} 640,${marginZeroY}`;
      const segments: string[] = [`0,${marginZeroY}`];
      let previousY = marginZeroY;
      orderedMarginPoints.forEach((point) => {
        const { x, y } = marginPointPosition(point);
        segments.push(`${x},${previousY}`, `${x},${y}`);
        previousY = y;
      });
    segments.push(`640,${previousY}`);
    return segments.join(' ');
  })();
  const marginAreaPoints = `${marginStepLine} 640,${marginZeroY} 0,${marginZeroY}`;
  const marginPointTitle = (point: GameEvent) => {
    const madeLog = `${TEAM_SHORT[point.team]}${point.playerNumber || '-'}_${point.zoneId || 'ZONE'}_Made`;
    return `${eventTime(point.period, point.clock)} · ${point.homeScoreAfter}-${point.awayScoreAfter} · ${madeLog} · ${point.team} #${point.playerNumber || '-'} MADE ${point.points || 0}PT`;
  };
  const marginPointTooltipLines = (point: GameEvent) => {
    const zoneLog = `${TEAM_SHORT[point.team]}${point.playerNumber || '-'}_${point.zoneId || 'ZONE'}_Made`;
    return [
      `${eventTime(point.period, point.clock)} · ${point.homeScoreAfter}-${point.awayScoreAfter}`,
      zoneLog,
      `${point.team} #${point.playerNumber || '-'} MADE ${point.points || 0}PT`,
    ];
  };

  return (
    <main className="page-stack basketball-page">
      <section className="basketball-scoreboard">
        <div className="basketball-score-team">
          <span>{homeName}</span>
          <strong>{score.home}</strong>
        </div>
        <div className="basketball-score-team away">
          <strong>{score.away}</strong>
          <span>{awayName}</span>
        </div>
        <div className="basketball-score-center">
          <div className="basketball-clock-row">
            <input value={clock} onChange={(e) => setClock(e.target.value)} aria-label="Clock" />
            <select
              value={period}
              onChange={(e) => {
                setTimerRunning(false);
                setTimerResetArmed(false);
                setPeriod(Number(e.target.value));
                setClock(formatClockSeconds(periodMinutes * 60));
              }}
              aria-label="Quarter"
            >
              {Array.from({ length: periodCount }, (_, index) => index + 1).map((item) => (
                <option key={item} value={item}>{item}Q</option>
              ))}
            </select>
            <button
              className="button-compact btn-secondary"
              onClick={() => {
                setTimerResetArmed(false);
                setTimerRunning((prev) => !prev);
              }}
            >
              {timerRunning ? 'Pause' : 'Start'}
            </button>
            <button className={`button-compact ${timerResetArmed ? 'btn-danger' : 'btn-secondary'}`} onClick={resetTimer}>
              {timerResetArmed ? 'Confirm' : 'Reset'}
            </button>
          </div>
          <span>{periodCount}Q × {periodMinutes}분 · Basketball FLA</span>
        </div>
      </section>

      {error ? <p className="form-error">{error}</p> : null}

      {isLineupEditorOpen ? (
        <div className="fcm-modal-backdrop" role="presentation" onClick={() => setIsLineupEditorOpen(false)}>
          <div
            aria-modal="true"
            className="card card-panel fcm-modal basketball-lineup-modal"
            role="dialog"
            aria-label="Basketball lineup editor"
            onClick={(event) => event.stopPropagation()}
          >
            <div className="section-heading">
              <div>
                <div className="sidebar-eyebrow">Lineup Editor</div>
                <h3>명단 편집</h3>
              </div>
              <button className="button-compact btn-secondary" onClick={() => setIsLineupEditorOpen(false)}>Close</button>
            </div>

            <div className="basketball-lineup-editor-grid">
              {(['HOME', 'AWAY'] as Team[]).map((side) => (
                <div className="basketball-lineup-editor-panel" key={side}>
                  <div className="row" style={{ justifyContent: 'space-between' }}>
                    <strong>{side === 'HOME' ? homeName : awayName}</strong>
                    <button className="button-compact btn-secondary" onClick={() => addLineupPlayer(side)}>Add</button>
                  </div>
                  <div className="basketball-lineup-table-wrap editor">
                    <table className="basketball-lineup-table editor">
                      <thead>
                        <tr>
                          <th>No.</th>
                          <th>Name</th>
                          <th>POS</th>
                          <th></th>
                        </tr>
                      </thead>
                      <tbody>
                        {lineups[side].map((player, index) => (
                          <tr key={`${side}-edit-${index}`}>
                            <td>
                              <input
                                value={player.number}
                                onChange={(event) => updateLineupPlayer(side, index, 'number', event.target.value)}
                                placeholder="No."
                                inputMode="numeric"
                              />
                            </td>
                            <td>
                              <input
                                value={player.name}
                                onChange={(event) => updateLineupPlayer(side, index, 'name', event.target.value)}
                                placeholder="Player"
                              />
                            </td>
                            <td>
                              <select
                                value={player.position && ['C', 'F', 'G'].includes(player.position) ? player.position : ''}
                                onChange={(event) => updateLineupPlayer(side, index, 'position', event.target.value)}
                                aria-label="Position"
                              >
                                <option value="">-</option>
                                <option value="C">C</option>
                                <option value="F">F</option>
                                <option value="G">G</option>
                              </select>
                            </td>
                            <td>
                              <button className="button-compact btn-danger" onClick={() => removeLineupPlayer(side, index)}>Remove</button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      ) : null}

      <section className="basketball-live-grid">
        <div className="basketball-main-stack">
          <div className="card card-panel basketball-court-card">
            <div className="section-heading">
              <div>
                <div className="sidebar-eyebrow">Shot Zone Map</div>
                <h3>샷맵</h3>
              </div>
            </div>

            <svg viewBox={`0 0 ${COURT_IMAGE_WIDTH} ${COURT_IMAGE_HEIGHT}`} className="basketball-court" role="img" aria-label="Basketball shot zone map">
              <rect x="0" y="0" width={COURT_IMAGE_WIDTH} height={COURT_IMAGE_HEIGHT} className="basketball-zone-map-base" />
              {ZONES.map((zone) => {
                const isSelected = selectedShot?.zoneId === zone.id;
                return (
                  <g key={zone.id}>
                    <path
                      d={zone.d}
                      className={isSelected ? 'selected-zone' : 'shot-zone'}
                      onClick={(event) => {
                        const rect = event.currentTarget.ownerSVGElement?.getBoundingClientRect();
                        if (!rect) return;
                        setSelectedShot({
                          zoneId: zone.id,
                          x: Math.max(0, Math.min(1, (event.clientX - rect.left) / rect.width)),
                          y: Math.max(0, Math.min(1, (event.clientY - rect.top) / rect.height)),
                        });
                        setSelectedShotEntryMode('COURT');
                      }}
                    />
                  </g>
                );
              })}
              <image
                href="/basketball-shot-zones.png"
                x="0"
                y="0"
                width={COURT_IMAGE_WIDTH}
                height={COURT_IMAGE_HEIGHT}
                preserveAspectRatio="none"
                className="basketball-zone-boundaries"
              />
            </svg>
          </div>

          <div className="card card-panel basketball-event-card">
            <div className="section-heading">
              <div>
                <div className="sidebar-eyebrow">Event Log</div>
                <h3>이벤트 로그</h3>
              </div>
            </div>
            <div className="basketball-event-log">
              {events.length === 0 ? <div className="muted">No events yet.</div> : null}
              {events.slice().reverse().map((event) => (
                <div key={event.id} className="basketball-event-row">
                  <span>{eventTime(event.period, event.clock)}</span>
                  <strong>
                    {event.type === 'SHOT'
                      ? `${event.team} #${event.playerNumber || '-'} ${event.shotResult} ${event.points}PT`
                      : `${event.team} ${event.reboundType}${event.reboundAllowedTeam ? ` · ${event.reboundAllowedTeam} RA` : ''}`}
                  </strong>
                  <span>{event.zoneId === 'FREE_THROW_ZONE' ? 'free throw zone' : event.zoneId || ''}</span>
                  <span>{event.homeScoreAfter} - {event.awayScoreAfter}</span>
                </div>
              ))}
            </div>
          </div>

        </div>

        <aside className="basketball-control-stack">
          <div className="card card-panel">
            <div className="section-heading">
              <div>
                <div className="sidebar-eyebrow">Lineup</div>
                <h3>입력 선택</h3>
              </div>
              <button className="button-compact btn-secondary" onClick={() => setIsLineupEditorOpen(true)}>명단 편집</button>
            </div>
            <div className="basketball-lineup-split-grid">
              {(['HOME', 'AWAY'] as Team[]).map((side) => (
                <div className="basketball-lineup-side" key={side}>
                  <div className="basketball-lineup-side-title">
                    <strong>{side === 'HOME' ? homeName : awayName}</strong>
                    <span>{TEAM_SHORT[side]}</span>
                  </div>
                  <div className="basketball-lineup-table-wrap">
                    <table className="basketball-lineup-table">
                      <thead>
                        <tr>
                          <th>No.</th>
                          <th>Name</th>
                          <th>POS</th>
                        </tr>
                      </thead>
                      <tbody>
                        {lineups[side].map((player) => {
                          const active = side === selectedTeam && player.number === selectedPlayer;
                          return (
                            <tr
                              key={`${side}-${player.number}-${player.name}`}
                              className={active ? 'active' : ''}
                              onClick={() => {
                                setSelectedTeam(side);
                                setSelectedPlayer(player.number);
                              }}
                            >
                              <td>#{player.number || '-'}</td>
                              <td>{player.name || '-'}</td>
                              <td>{player.position || '-'}</td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>
                </div>
              ))}
            </div>
            <div className="basketball-shot-actions">
              <div className="muted">선택 선수: {TEAM_SHORT[selectedTeam]} #{selectedPlayer} {selectedPlayerRow?.name || ''}</div>
              <div className="muted">선택 구역: {selectedShotEntryMode === 'FREE_THROW' ? 'free throw zone' : selectedShot?.zoneId || '코트에서 선택'}</div>
              <button
                className={selectedShotEntryMode === 'COURT' && selectedShotResult === 'MADE' ? 'btn-primary active' : 'btn-secondary'}
                onClick={() => {
                  setSelectedShotEntryMode('COURT');
                  setSelectedShotResult('MADE');
                }}
              >
                Made
              </button>
              <button
                className={selectedShotEntryMode === 'COURT' && selectedShotResult === 'MISSED' ? 'btn-danger active' : 'btn-secondary'}
                onClick={() => {
                  setSelectedShotEntryMode('COURT');
                  setSelectedShotResult('MISSED');
                }}
              >
                Missed
              </button>
              <button
                className={selectedShotEntryMode === 'FREE_THROW' ? 'btn-primary active' : 'btn-secondary'}
                onClick={() => {
                  setSelectedShotEntryMode('FREE_THROW');
                  setSelectedShot(null);
                  setSelectedShotResult('MADE');
                }}
                disabled={!selectedPlayer.trim()}
              >
                Free Throw
              </button>
              <div className="basketball-log-entry-row">
                <input value={shotLogPreview} readOnly aria-label="Shot log preview" />
                <button className="btn-primary" onClick={addShot} disabled={!canSubmitShot}>입력</button>
              </div>
            </div>
          </div>

          <div className="card card-panel">
            <div className="section-heading">
              <div>
                <div className="sidebar-eyebrow">Rebound</div>
                <h3>리바운드 입력</h3>
              </div>
            </div>
            <div className="basketball-rebound-picker">
              <button
                className={selectedReboundTeam === 'HOME' ? 'active' : ''}
                onClick={() => setSelectedReboundTeam('HOME')}
              >
                {homeName}
              </button>
              <button
                className={selectedReboundTeam === 'AWAY' ? 'active' : ''}
                onClick={() => setSelectedReboundTeam('AWAY')}
              >
                {awayName}
              </button>
              <button
                className={selectedReboundType === 'DR' ? 'active' : ''}
                onClick={() => setSelectedReboundType('DR')}
              >
                DR
              </button>
              <button
                className={selectedReboundType === 'AR' ? 'active' : ''}
                onClick={() => setSelectedReboundType('AR')}
              >
                AR
              </button>
            </div>
            <div className="basketball-log-entry-row rebound">
              <input value={reboundLogPreview} readOnly aria-label="Rebound log preview" />
              <button className="btn-primary" onClick={addRebound} disabled={!canSubmitRebound}>입력</button>
            </div>
          </div>

          <div className="card card-panel basketball-rebound-control-card">
            <div className="section-heading">
              <div>
                <div className="sidebar-eyebrow">Rebound Control</div>
              </div>
            </div>
            <div className="basketball-rebound-control-grid">
              {(['HOME', 'AWAY'] as Team[]).map((side) => {
                const view = reboundStats[side];
                const total = view.ar + view.dr + view.ra;
                return (
                  <div className="basketball-rebound-control-side" key={side}>
                    <div className="row" style={{ justifyContent: 'space-between', alignItems: 'baseline' }}>
                      <strong>{side === 'HOME' ? homeName : awayName}</strong>
                      <span className="muted">{total}</span>
                    </div>
                    <div className="basketball-rebound-bars">
                      {(['ar', 'dr', 'ra'] as const).map((key) => {
                        const value = view[key];
                        const pct = total > 0 ? Math.round((value / total) * 100) : 0;
                        return (
                          <div key={key}>
                            <div className="row" style={{ justifyContent: 'space-between' }}>
                              <span>{key.toUpperCase()}</span>
                              <strong>{value} · {pct}%</strong>
                            </div>
                            <div className="basketball-bar"><span style={{ width: `${pct}%` }} /></div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </aside>
      </section>

      <section className="basketball-bottom-grid">
        <div className="card card-panel">
          <div className="section-heading">
            <div>
              <div className="sidebar-eyebrow">Margin Flow</div>
            </div>
          </div>
          <svg viewBox="-42 0 682 244" preserveAspectRatio="none" className="basketball-margin-chart" role="img" aria-label="Margin flow chart">
            <defs>
              <clipPath id="basketball-margin-positive">
                <rect x="0" y="0" width="640" height={marginZeroY} />
              </clipPath>
              <clipPath id="basketball-margin-negative">
                <rect x="0" y={marginZeroY} width="640" height={244 - marginZeroY} />
              </clipPath>
            </defs>
            <g className="margin-grid">
              {marginGridXTicks.map((x) => (
                <line key={`grid-x-${x}`} x1={x} x2={x} y1="12" y2="208" />
              ))}
              {marginGridYTicks.map((tick) => (
                <g key={`grid-y-${tick.value}`}>
                  <line x1="0" x2="640" y1={tick.y} y2={tick.y} />
                  <text x="-8" y={Math.max(18, tick.y + 3)} textAnchor="end">{Math.round(tick.value)}</text>
                </g>
              ))}
            </g>
            <polygon points={marginAreaPoints} className="margin-fill-home" clipPath="url(#basketball-margin-positive)" />
            <polygon points={marginAreaPoints} className="margin-fill-away" clipPath="url(#basketball-margin-negative)" />
            <line x1="0" x2="640" y1={marginZeroY} y2={marginZeroY} className="zero-line" />
            {quarterMarkers.map((marker) => (
              <g key={marker.label} className="quarter-marker">
                <line x1={marker.x} x2={marker.x} y1="8" y2="212" />
                <text x={Math.min(632, marker.x + 7)} y="22">{marker.label}</text>
              </g>
            ))}
            <polyline points={marginStepLine} className="margin-line" />
            {orderedMarginPoints.map((point) => {
              const { x, y } = marginPointPosition(point);
              return (
                <g key={point.id}>
                  <circle
                    cx={x}
                    cy={y}
                    r="10"
                    className="margin-dot-hit"
                    onMouseEnter={() => setMarginTooltip({ id: point.id, x, y, lines: marginPointTooltipLines(point) })}
                    onMouseMove={() => setMarginTooltip({ id: point.id, x, y, lines: marginPointTooltipLines(point) })}
                    onMouseLeave={() => setMarginTooltip(null)}
                  />
                  <circle cx={x} cy={y} r="3.4" className={point.team === 'HOME' ? 'home-dot' : 'away-dot'} />
                </g>
              );
            })}
            {marginTooltip ? (
              <g className="margin-tooltip" pointerEvents="none" transform={`translate(${Math.min(470, Math.max(8, marginTooltip.x + 10))} ${Math.max(18, marginTooltip.y - 58)})`}>
                <rect width="162" height="48" rx="6" />
                {marginTooltip.lines.map((line, index) => (
                  <text key={`${marginTooltip.id}-${index}`} x="8" y={14 + index * 14}>{line}</text>
                ))}
              </g>
            ) : null}
            <g className="margin-time-axis">
              <line x1="0" x2="640" y1="218" y2="218" />
              {marginAxisTicks.map((tick) => (
                <g key={`${tick.x}-${tick.label}`}>
                  <line x1={tick.x} x2={tick.x} y1="214" y2="222" />
                  <text x={Math.min(632, Math.max(8, tick.x))} y="236" textAnchor={tick.x < 16 ? 'start' : tick.x > 624 ? 'end' : 'middle'}>
                    {tick.label}
                  </text>
                </g>
              ))}
            </g>
          </svg>
        </div>
      </section>
    </main>
  );
}
